function setNestedKey(obj, dotPath, value) {
  const parts = dotPath.split(".");
  let cur = obj;
  for (let i = 0; i < parts.length - 1; i++) {
    if (typeof cur[parts[i]] !== "object" || cur[parts[i]] === null) cur[parts[i]] = {};
    cur = cur[parts[i]];
  }
  cur[parts[parts.length - 1]] = value;
}

const locales = ["en", "cs", "sk", "es", "de", "fr", "pt", "it", "pl", "nl"];

for (const locale of locales) {
  const filePath = `locales/${locale}.json`;
  const raw = fs.readFileSync(filePath, "utf-8").replace(/^﻿/, "");
  const data = JSON.parse(raw);

  if (locale === "en") {
    for (const [dotPath, value] of Object.entries(EN_REWRITES)) {
      setNestedKey(data, dotPath, value);
    }
  } else {
    for (const [key, byLocale] of Object.entries(TRANSLATIONS)) {
      if (byLocale[locale] !== undefined) {
        setNestedKey(data, key, byLocale[locale]);
      }
    }
  }

  fs.writeFileSync(filePath, JSON.stringify(data, null, 2) + "\n");
  console.log(`Updated ${locale}.json`);
}

console.log("Done.");
